The file tools aren't resolving via ToolSearch. Here's the complete implementation you can save as `ErrorBoundary.tsx`:

```tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false, error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    this.setState({ errorInfo: info });
    console.error("[ErrorBoundary] Caught error:", error);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
    this.props.onError?.(error, info);
  }

  handleRetry = (): void => {
    this.setState({ hasError: false, error: null, errorInfo: null });
  };

  render(): ReactNode {
    if (!this.state.hasError) {
      return this.props.children;
    }

    if (this.props.fallback) {
      return this.props.fallback;
    }

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.title}>Something went wrong</h2>
        <p style={styles.message}>{this.state.error?.message}</p>
        <details style={styles.details}>
          <summary>Stack trace</summary>
          <pre style={styles.stack}>
            {this.state.errorInfo?.componentStack}
          </pre>
        </details>
        <button onClick={this.handleRetry} style={styles.button}>
          Retry
        </button>
      </div>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "0.5rem",
    backgroundColor: "#fef2f2",
    color: "#991b1b",
    maxWidth: "600px",
    margin: "2rem auto",
    fontFamily: "sans-serif",
  },
  title: { margin: "0 0 0.5rem", fontSize: "1.25rem" },
  message: { margin: "0 0 1rem", color: "#b91c1c" },
  details: { marginBottom: "1rem" },
  stack: {
    fontSize: "0.75rem",
    overflowX: "auto",
    whiteSpace: "pre-wrap",
    color: "#374151",
  },
  button: {
    padding: "0.5rem 1.25rem",
    backgroundColor: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "0.375rem",
    cursor: "pointer",
    fontSize: "0.875rem",
  },
};
```

**Usage:**

```tsx
// Basic wrapping
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// With custom fallback UI
<ErrorBoundary fallback={<p>Custom error UI</p>}>
  <MyComponent />
</ErrorBoundary>

// With external error logger (e.g. Sentry)
<ErrorBoundary onError={(err, info) => Sentry.captureException(err, { extra: info })}>
  <MyComponent />
</ErrorBoundary>
```

**Key points:**
- `getDerivedStateFromError` triggers the fallback render synchronously
- `componentDidCatch` fires after render for logging side effects — both `console.error` and the optional `onError` callback
- Retry resets state, which re-mounts `children`; if the underlying bug is still present, it will catch again immediately
- Must be a class component — hooks can't implement `componentDidCatch`
